handlers.callSearchSTSGrid:
function callSearchSTSGrid(flag) {	
	var retVal = $("#webhookList").jqGrid('setGridParam', {
		datatype : 'json',
		page : 1,		
		postData : {
				docId : $("#gs_docId").val(),
				docType : $("#gs_docType").val(),
				docStatus : $("#gs_docStatus").val(),
				responseCode : $("#gs_responseCode").val(),
				sellerId : $("#gs_sellerId").val(),
				rowVersion : $("#gs_rowVersion").val(),
				fromCreateDate : $("#fromCreatedDate").val(),        
				toCreateDate : $("#toCreatedDate").val(), 
				REQ_SEARCH_FLAG : REQ_SEARCH_FLAG,
				 doFetchCount : false
			},
			url : "jsonWebHookSearch",
			search : true
		}).trigger('reloadGrid');
		REQ_SEARCH_FLAG=true;
	}

handlers.repushUpdate:
function repushUpdate () {
		var gridObj = jQuery("#webhookList");
		var selRowId = gridObj.jqGrid ('getGridParam', 'selarrrow');
		var webhookKeys  = "";
		if(selRowId != undefined && selRowId.length > 0) {

			var idsLen = selRowId.length;

			for (var i = 0; i < idsLen; i++) 
			{
			    var rowId = selRowId[i];
			    var rowData = gridObj.jqGrid('getRowData', rowId);

			    if(rowData.webhookKey == undefined || rowData.webhookKey == "" || rowData.webhookKey == null){
					window.parent.showAlert("");
					return false;
			    }
			    else {					    
			    	webhookKeys += (webhookKeys.length > 0) ? "," : "";
			    	webhookKeys += rowData.webhookKey;
			    }					    					    
			}

				var retVal = $.ajax({
				url : "repushUpdateList",

				type : "POST",
				data : {
					webhookKeys : webhookKeys
				},
				dataType : "json",
				async : false
			}).responseText;

			retVal = jQuery.parseJSON(retVal);
			if(retVal != null && retVal != undefined && retVal.jsonMessage == null){
				jQuery("#webhookList").trigger("reloadGrid");
				window.parent.showAlert('Records Repushed Successfully');
				return true;
			}
		}
			else{
				window.parent.showAlert('Please Select Grid Row For Repush'); // VE-53935 S-E
				return false;
			}
	}

handlers.resetAll:
function resetAll() {

		$("#webhookList").jqGrid('clearGridData', {
			clearfooter : true
		});
		$("#gs_docId").val('');
		$("#gs_docType").val('-1');
		$("#gs_docStatus").val('-1');
		$("#gs_responseCode").val("999");
		$("#gs_sellerId").val('');
		$("#gs_rowVersion").val('');
		var dateformat='dd/mm/yy';
	     var oldDate = new Date(); 
	     var currdate = new Date(); 
	     oldDate.setDate(oldDate.getDate() - (7)); 
	     var formattedold = $.datepicker.formatDate(dateformat,oldDate);
	     var formattednew = $.datepicker.formatDate(dateformat,currdate);
	     $("#fromCreatedDate").val(formattedold);
	     $("#toCreatedDate").val(formattednew);
	     $('#gs_createDate').val(formattedold+" - "+formattednew);
		fillGridDropDown();

}

handlers.displaybtn:
function displaybtn(obj) {
	    if (obj == "emailTransit") {
	        $("#emailTransittab").show();
	        $("#transmitDetailtab").hide();
	        $("#manifestStatustab").hide();
	        $("#webhooktab").hide();
	        emailTransitGrid();
	    } else if (obj == "transmitDetail") {
	    	$("#emailTransittab").hide();
	        $("#transmitDetailtab").show();
	        $("#manifestStatustab").hide();
	        $("#webhooktab").hide();
	        transmitDetailGrid();
	    }
	    else if (obj == "manifestStatus") {
	    	$("#emailTransittab").hide();
	        $("#transmitDetailtab").hide();
	        $("#manifestStatustab").show();
	        $("#webhooktab").hide();
	        manifestStatusGrid();
	    }
	    else{
	    	$("#emailTransittab").hide();
	        $("#transmitDetailtab").hide();
	        $("#manifestStatustab").hide();
	        $("#webhooktab").show();
	    }
	}
